(function () {
  const parseParts = (s) => (s ? s.split('|').map((p) => { const i = p.indexOf('='); return [p.slice(0, i), p.slice(i + 1)]; }) : null);
  window.ITEMS_LIST = [];
  window.HEAR_ONLY = new Set();
  window.UNITS.forEach((u) => {
    u.items = u.items.map((r) => {
      const it = { id: 'c:' + r[0], unit: u.id, kind: u.kind, jp: r[0], kana: r[1], romaji: r[2], es: r[3], note: r[4] || '', parts: parseParts(r[5]), hear: r[6] === 'oir' };
      if (it.hear) window.HEAR_ONLY.add(it.id);
      window.ITEMS_LIST.push(it);
      return it;
    });
  });
})();
